/* === 小屁孩日记 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影. === */

/* --- 1. 字体引入 --- */
@import url('https://fonts.googleapis.com/css2?family=Gloria+Hallelujah&family=Patrick+Hand&display=swap');
@import url("https://fontsapi.zeoseven.com/200/main/result.css"); /* 中文全局字体: cjkFonts 全瀨體 */
@import url("https://fontsapi.zeoseven.com/45/main/result.css");  /* 被代码块包裹的字体: nzgrRuYinZouZhangKai */
@import url("https://fontsapi.zeoseven.com/500/main/result.css"); /* 被引号包裹的字体: PING FANG SAI BEI */
@import url("https://fontsapi.zeoseven.com/20/main/result.css");  /* 一级标题二级标题字体: Xiangcui Wave Sans Xiangcui Wave Sans */

/* --- 2. 核心颜色与样式变量 (白/蓝为主，美式复古校园) --- */
:root {
    --theme-bg-color: #F0F4F8; 
    --theme-bg-mid: #D9E2EC; 
    --card-bg: rgba(255, 255, 255, 0.95); /* 文件夹白 */
    --accent-blue: #1C3F60; /* 复古学院蓝 */
    --accent-red: #D9534F; /* 学院红点缀 */
    --accent-gold: #F0AD4E; /* 铅笔黄 */
    --accent-green: #5CB85C; /* 索引贴绿 */
    --accent-lightblue: #5BC0DE; /* 索引贴浅蓝 */
    --text-main: #2C3E50; /* 墨水蓝黑 */
    --text-subtle: #5D6D7E; /* 浅墨水色 */

    --font-english-script: 'Gloria Hallelujah', cursive;
    --font-english-serif: 'Patrick Hand', cursive;
    --font-main: "cjkFonts 全瀨體", var(--font-english-serif), sans-serif;
    --font-quote: "PING FANG SAI BEI", var(--font-english-script), serif;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "Xiangcui Wave Sans Xiangcui Wave Sans", var(--font-english-script), sans-serif;
}

/* --- 3. 全局样式：无阴影、无边框、日记本背景 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg-color) !important; 
    background-image: repeating-linear-gradient(transparent, transparent 29px, rgba(28, 63, 96, 0.08) 29px, rgba(28, 63, 96, 0.08) 30px) !important; 
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--accent-blue); font-weight: normal; }

/* --- 4. 顶部导航栏 & 抽屉背景 (贴图替换) --- */
#top-settings-holder { position:relative; background-color: rgba(255, 255, 255, 0.7); backdrop-filter: blur(10px); border: none !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); }
.drawer-icon.fa-fw:hover { transform: translateY(-3px) scale(1.1) rotate(5deg); }

/* 自定义导航栏贴图 */
.drawer-icon.fa-sliders, .drawer-icon.fa-font, .drawer-icon.fa-user, .drawer-icon.fa-cubes, .drawer-icon.fa-face-smile, #ai-config-button .drawer-icon, #advanced-formatting-button .drawer-icon, #user-settings-button .drawer-icon, #extensions-settings-button .drawer-icon, #persona-management-button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/3cOw/1448X1599/2026-05-02_002333.png/webp'); 
}
.drawer-icon.fa-plug, .drawer-icon.fa-book-atlas, .drawer-icon.fa-image, .drawer-icon.fa-bars-progress, .drawer-icon.fa-panorama, #sys-settings-button .drawer-icon, #WI-SP-button .drawer-icon, #table_database_settings_drawer .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/dCyU/1158X1537/2026-05-02_002343.png/webp'); 
}
.drawer-icon.fa-address-card, #character_popup_button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/k05x/1313X1835/2026-05-01_232328.png/webp'); 
}

/* 抽屉与弹窗背景图 */
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(240, 244, 248, 0.85), rgba(240, 244, 248, 0.95)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/9tE1/1199X960/52cab34228361ded6ece86541be07685.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 8px !important; color: var(--text-main) !important;
}

/* --- 5. 底部悬浮输入栏 --- */
#form_sheld { position: absolute !important; bottom: 10px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { width: 90% !important; max-width: 800px !important; pointer-events: auto; }

#send_form, body.no-blur #send_form { 
    border-radius: 25px !important; 
    background-color: rgba(255, 255, 255, 0.8) !important; 
    padding: 10px 15px !important; 
    backdrop-filter: blur(10px) !important; 
    -webkit-backdrop-filter: blur(10px) !important; 
    border: none !important; 
    box-shadow: none !important; 
    transition: all 0.3s ease !important; 
}
#send_form:hover, body.no-blur #send_form:hover { transform: translateY(-5px); background-color: rgba(255, 255, 255, 0.95) !important; }

#rightSendForm, #leftSendForm { gap: 10px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; font-size: 1.1rem !important; box-shadow: none !important; font-family: var(--font-english-serif); }

#nonQRFormItems { position: relative; }
#send_textarea::placeholder { color: transparent !important; text-shadow: none !important; }

/* 伪提示词 (Diary of a Wimpy Kid Theme) */
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: 'Writing in my secret diary... 📓✏️'; 
    color: var(--accent-blue); 
    position: absolute; 
    top: 50%; transform: translateY(-50%); 
    left: 50px; right: 70px; 
    text-align: center; 
    font-family: var(--font-english-script); 
    font-size: clamp(1rem, 2.5vw, 1.4rem); 
    pointer-events: none; 
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    opacity: 0.7; 
    animation: scribble-shake 3s infinite alternate;
}
@keyframes scribble-shake { 0% { transform: translateY(-50%) rotate(-1deg); } 100% { transform: translateY(-50%) rotate(1deg); } }

/* 底栏贴图 */
#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before, #mes_impersonate::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button, #mes_impersonate { 
    width: 36px; height: 36px; 
    background-size: contain; background-repeat: no-repeat; background-position: center; 
    transition: transform 0.2s ease; font-size: 0; border: none; background-color: transparent; 
}
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover, #mes_impersonate:hover { transform: scale(1.15) rotate(10deg); }

#options_button, #ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/cyzN/1655X1497/2026-05-02_002305.png/webp'); }
#send_form #extensionsMenuButton, #auto_completion_button, #mes_impersonate { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/hfPY/1561X999/2026-05-02_002316.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/gBgi/1425X1601/2026-05-02_002255.png/webp'); }

/* --- 6. 核心：消息框 (大画幅+实体文件夹) --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 140px auto 60px !important; 
    width: 90%; max-width: 800px; 
    background-color: transparent !important;
}

/* --- 消息框顶部背景图 --- */
.mes .mesAvatarWrapper {
    display: block; padding: 0;
    width: 100%; 
    height: 400px !important; 
    min-height: 400px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-radius: 8px;
    border: none !important; 
    background-color: transparent !important; 
}
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/YTxk/4578X2298/2026-05-02%2520000053.png/webp'); }
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/kVQK/4578X2298/2026-05-02%2520000555.png/webp'); }

/* 顶端图钉效果 */
.mes .mesAvatarWrapper::before {
    content: '📌'; position: absolute; top: -18px; left: 50%; transform: translateX(-50%);
    font-size: 38px; z-index: 40;
}
/* 文件夹顶部突出的索引标签 (Folder Top Tab) */
.mes .mes_block::before {
    position: absolute;
    top: -26px; /* 标签贴在文件夹正上方 */
    height: 26px;
    width: 140px;
    background-color: var(--card-bg);
    border: 1px solid var(--theme-bg-mid);
    border-bottom: none;
    font-family: var(--font-english-script);
    font-size: 14px;
    line-height: 26px;
    text-align: center;
    z-index: 20;
    letter-spacing: 1px;
}

/* AI 的文件夹造型 (顶部标签偏左) */
.mes[is_user="false"] .mes_block { border-radius: 0 12px 12px 12px !important; }
.mes[is_user="false"] .mes_block::before { 
    content: 'FILE: CONFIDENTIAL'; 
    left: -1px; 
    border-radius: 8px 8px 0 0; 
    color: var(--accent-red); 
}

/* 用户的文件夹造型 (顶部标签偏右) */
.mes[is_user="true"] .mes_block { border-radius: 12px 0 12px 12px !important; }
.mes[is_user="true"] .mes_block::before { 
    content: 'NOTES: PERSONAL'; 
    right: -1px; left: auto; 
    border-radius: 8px 8px 0 0; 
    color: var(--accent-blue); 
}
/* --- 6. 核心：消息框 (大画幅+实体文件夹) --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 140px auto 60px !important; 
    width: 90%; max-width: 800px; 
    background-color: transparent !important;
}

/* --- 消息框顶部背景图 --- */
.mes .mesAvatarWrapper {
    display: block; padding: 0;
    width: 100%; 
    height: 400px !important; 
    min-height: 400px !important;
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 5; overflow: visible !important;
    border-radius: 8px;
    border: none !important; 
    background-color: transparent !important; 
}
.mes[is_user="false"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/YTxk/4578X2298/2026-05-02%2520000053.png/webp'); }
.mes[is_user="true"] .mesAvatarWrapper { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/kVQK/4578X2298/2026-05-02%2520000555.png/webp'); }

/* 顶端图钉效果 */
.mes .mesAvatarWrapper::before {
    content: '📌'; position: absolute; top: -18px; left: 50%; transform: translateX(-50%);
    font-size: 38px; z-index: 40;
}

/* --- 学生证风格头像框 --- */
.mes .avatar {
    position: absolute;
    top: 50%; 
    width: 200px !important; height: 260px !important; 
    background: #FFF !important; 
    padding: 14px 14px 55px 14px !important; 
    z-index: 30; display: flex !important; align-items: flex-start; justify-content: center;
    border-radius: 4px !important; 
    border: 1px solid #d1d5db !important;
}
.mes[is_user="false"] .avatar { left: 20px; transform: translateY(-50%) rotate(-4deg); }
.mes[is_user="true"] .avatar { right: 20px; left: auto; transform: translateY(-50%) rotate(4deg); }

.mes .avatar img { 
    width: 100% !important; height: 100% !important; 
    object-fit: cover !important; border-radius: 2px !important; 
}

/* 学生证胶带与条码信息 */
.mes .avatar::before {
    content: ''; position: absolute; top: -14px; left: 50%; transform: translateX(-50%) rotate(3deg);
    width: 65px; height: 30px; background-color: rgba(255, 255, 255, 0.7);
    border: 1px solid rgba(0,0,0,0.05); z-index: 40; backdrop-filter: blur(2px);
}
.mes .avatar::after {
    content: 'STUDENT ID \A ||| || ||| | ||| ||'; white-space: pre; position: absolute;
    bottom: 12px; left: 0; right: 0; text-align: center;
    font-family: monospace; font-size: 12px; color: #4b5563; line-height: 1.2; letter-spacing: 1px;
}

/* --- 名字 --- */
.mes > .ch_name, .mes .mes_block > .ch_name { 
    display: flex !important; position: absolute; 
    bottom: 20px !important; top: auto !important;
    background: rgba(255, 255, 255, 0.9) !important;
    border: none !important;
    border-radius: 0 !important;
    padding: 8px 20px !important; 
    z-index: 40; align-items: center !important; gap: 12px !important;
    transform: rotate(-2deg);
}
.mes[is_user="false"] > .ch_name, .mes[is_user="false"] .mes_block > .ch_name { left: 250px !important; right: auto !important; }
.mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { right: 250px !important; left: auto !important; }

.mes .ch_name .name_text { font-family: var(--font-english-script); font-size: 26px !important; letter-spacing: 1px; color: var(--accent-blue) !important; text-transform: uppercase; }

/* --- 楼层与时间戳 (左右分离) --- */
.mes .mesIDDisplay, .mes .mes_timer {
    position: absolute !important; top: -18px !important; 
    background-color: #F0AD4E !important; padding: 6px 16px !important;
    color: #fff !important; font-size: 15px !important; font-family: var(--font-english-serif) !important; 
    letter-spacing: 1px !important; white-space: nowrap; z-index: 40 !important;
    border: none !important;
    border-radius: 4px !important;
}
.mes .mesIDDisplay { left: 30px !important; transform: rotate(-2deg) !important; }
.mes .mes_timer { right: 30px !important; left: auto !important; transform: rotate(2deg) !important; }
.mesIDDisplay::before { content: 'Diary Page. '; }
.mesIDDisplay::after { content: ' 📝'; }



/* --- 楼层与时间戳 (左右分离) --- */
.mes .mesIDDisplay, .mes .mes_timer {
    position: absolute !important; top: -18px !important; 
    background-color: #F0AD4E !important; padding: 6px 16px !important;
    color: #fff !important; font-size: 15px !important; font-family: var(--font-english-serif) !important; 
    letter-spacing: 1px !important; white-space: nowrap; z-index: 40 !important;
    border: none !important;
    border-radius: 4px !important;
}
.mes .mesIDDisplay { left: 30px !important; transform: rotate(-2deg) !important; }
.mes .mes_timer { right: 30px !important; left: auto !important; transform: rotate(2deg) !important; }
.mesIDDisplay::before { content: 'Diary Page. '; }
.mesIDDisplay::after { content: ' 📝'; }

/* ========================================================
   电脑端专属微调：头像与名字向内侧（左右）收缩
======================================================== */
@media (min-width: 800px) {
    .mes[is_user="false"] .avatar { 
        left: 100px !important; 
    }


    /*  用户头像往左移动 (增大 right 的值，原为 20px，现改为 60px) */
    .mes[is_user="true"] .avatar { 
        right: 90px !important; 
    }
}


/* --- 消息正文：实体档案文件夹效果 (修复索引贴截断) --- */
.mes .mes_block { 
    margin-top: 50px !important; 
    background-color: var(--card-bg) !important; 
    padding: 40px !important; 
    position: relative; 
    border: 1px solid var(--theme-bg-mid) !important; 
    min-height: 120px !important; 
    z-index: 10; 
    background-image: none !important; 
    overflow: visible !important; /* 关键修复：允许内部元素（索引贴）伸出框外 */
    clip-path: none !important; /* 关键修复：解除防溢出遮罩 */
    -webkit-mask-image: none !important;
}

/* --- 文件夹侧边彩色索引贴 (Side Index Tabs) 修复截断问题 --- */
.mes .mes_block {
    overflow: visible !important; /* 强制允许内容溢出，防止边缘被原生UI截断 */
}

.mes .mes_block::after {
    content: '';
    position: absolute;
    top: 20px; /* 位置微调靠上 */
    width: 14px;
    height: 24px; /* 缩小单张贴纸的高度 */
    z-index: -1; 
}

/* AI 侧边贴 (右侧伸出) */
.mes[is_user="false"] .mes_block::after {
    right: -14px;
    background-color: var(--accent-gold); 
    border-radius: 0 6px 6px 0;
    border: 1px solid rgba(0,0,0,0.05); border-left: none;
    /* 缩小阴影间距，确保3张贴纸的总高度(约92px)完美包含在消息框的最小高度(120px)之内 */
    box-shadow: 
        0 34px 0 0 var(--accent-red), 
        0 68px 0 0 var(--accent-lightblue); 
}

/* User 侧边贴 (左侧伸出) */
.mes[is_user="true"] .mes_block::after {
    left: -14px;
    background-color: var(--accent-green); 
    border-radius: 6px 0 0 6px;
    border: 1px solid rgba(0,0,0,0.05); border-right: none;
    box-shadow: 
        0 34px 0 0 var(--accent-gold), 
        0 68px 0 0 var(--accent-blue); 
}

/* 手机端进一步缩小彩色侧边索引贴，完美适配短消息 */
@media (max-width: 768px) {
    .mes .mes_block::after {
        width: 10px; 
        height: 18px; 
        top: 15px;
    }
    .mes[is_user="false"] .mes_block::after { 
        right: -10px; 
        box-shadow: 0 26px 0 0 var(--accent-red), 0 52px 0 0 var(--accent-lightblue); 
    }
    .mes[is_user="true"] .mes_block::after { 
        left: -10px; 
        box-shadow: 0 26px 0 0 var(--accent-gold), 0 52px 0 0 var(--accent-blue); 
    }
}


/* 背景隐约的英文装饰涂鸦 */
.mes_block .mes_text::after {
    content: 'TOP SECRET \A DO NOT READ!'; white-space: pre;
    position: absolute; bottom: 10px; color: rgba(28, 63, 96, 0.04);
    font-family: var(--font-english-script); font-size: 45px; text-align: center; font-weight: bold; transform: rotate(-10deg);
    z-index: 0; pointer-events: none; user-select: none;
}
.mes[is_user="false"] .mes_block .mes_text::after { right: 20px; }
.mes[is_user="true"] .mes_block .mes_text::after { left: 20px; }

/* 思维链自定义 (Doodling) */
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; padding: 0 !important; margin-bottom: 15px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "🖍️ Doodling some thoughts... (Thinking)"; 
    font-family: var(--font-english-script); font-size: 24px !important; 
    color: var(--accent-blue); visibility: visible; letter-spacing: 1px; 
}
.mes_reasoning { padding-left: 20px !important; margin-bottom: 30px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 1.05em; position: relative; }
.mes_reasoning::before { 
    content: ''; position: absolute; left: 0; top: 5px; bottom: 5px; width: 4px; 
    background: repeating-linear-gradient(45deg, var(--accent-blue), var(--accent-blue) 4px, transparent 4px, transparent 8px);
}
.mes .mes_text { line-height: 2.2; color: var(--text-main); font-size: 16px; text-align: justify; letter-spacing: 0.5px; }

/* 打字指示器 */
#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260502/gBgi/1425X1601/2026-05-02_002255.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: scribble-shake 1s infinite alternate; border: none !important; height: 50px !important; width: 50px !important; margin: 15px auto !important; }
#typing_indicator .dot { display: none !important; }

/* --- 悬浮按钮 (复古小贴纸) --- */
.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 8px; opacity: 0; transition: opacity 0.4s ease; pointer-events: auto !important; margin-top: 15px; position: relative; z-index: 15; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: rgba(255, 255, 255, 0.9) !important; color: var(--accent-blue) !important; padding: 6px !important; border-radius: 4px !important; cursor: pointer; transition: all 0.3s ease; font-size: 14px !important; border: none !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-gold) !important; color: #fff !important; transform: scale(1.1) rotate(5deg); }

/* --- 全局UI设定 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: rgba(255, 255, 255, 0.8) !important; border-radius: 4px !important; padding: 12px 18px !important; margin-bottom: 10px !important; color: var(--text-main) !important; border: none !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: rgba(255,255,255,0.9) !important; color: var(--text-main) !important; border-radius: 4px !important; padding: 10px !important; border: none !important; font-family: var(--font-english-serif); }
input:focus, textarea:focus, select:focus { outline: none !important; background-color: #fff !important; }
.menu_button { background-color: rgba(255, 255, 255, 0.8) !important; color: var(--accent-blue) !important; transition: all 0.3s ease; border-radius: 4px !important; border: none !important; }
.menu_button:hover, .menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-blue) !important; color: white !important; transform: translateY(-2px); }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-red) !important; }

dialog.popup { background-color: transparent !important; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(255, 255, 255, 0.95); z-index: 0; border-radius: 8px; border: none !important; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }

#dialogue_popup { z-index: 10000 !important; pointer-events: auto !important; }
#dialogue_del_mes_ok, #dialogue_del_mes_cancel { background-color: rgba(255,255,255,0.9) !important; color: var(--accent-blue) !important; border-radius: 4px !important; padding: 12px 24px !important; margin: 10px 8px !important; transition: all 0.3s ease !important; border: none !important; }
#dialogue_del_mes_ok:hover { background-color: var(--accent-red) !important; color: #fff !important; transform: translateY(-2px) rotate(-2deg) !important; }
#dialogue_del_mes_cancel:hover { background-color: var(--accent-blue) !important; color: #fff !important; transform: translateY(-2px) rotate(2deg) !important; }

/* --- 手机端适配调整 --- */
@media (max-width: 768px) {
    .mes { margin: 120px auto 40px !important; }
    .mes .mesAvatarWrapper { height: 250px !important; min-height: 250px !important; margin-bottom: 30px; }
    .mes > .ch_name, .mes .mes_block > .ch_name { bottom: 10px !important; padding: 6px 14px !important; }

    /* 手机端同步避开扩大的头像 */
    .mes[is_user="false"] > .ch_name, .mes[is_user="false"] .mes_block > .ch_name { left: 170px !important; }
    .mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { right: 170px !important; }
    .mes .ch_name .name_text { font-size: 18px !important; }

    /* 手机端进一步放大的头像 */
    .mes .avatar { width: 140px !important; height: 190px !important; padding: 10px 10px 45px 10px !important; }
    .mes .avatar::after { font-size: 10px; bottom: 8px; }

    /* 手机端保持实体文件夹造型并缩放标签 */
    .mes .mes_block { 
        padding: 30px 20px 30px 20px !important; 
        margin-top: 30px !important; 
    }
    .mes .mes_block::before {
        width: 100px; height: 22px; line-height: 22px; top: -22px; font-size: 11px;
    }
    /* 缩小手机端的彩色侧边索引贴 */
    .mes .mes_block::after {
        width: 10px; height: 30px; top: 20px;
    }
    .mes[is_user="false"] .mes_block::after { right: -10px; box-shadow: 0 40px 0 0 var(--accent-red), 0 80px 0 0 var(--accent-lightblue); }
    .mes[is_user="true"] .mes_block::after { left: -10px; box-shadow: 0 40px 0 0 var(--accent-gold), 0 80px 0 0 var(--accent-blue); }

    /* 手机端的楼层/时间错位 */
    .mes .mesIDDisplay { left: 10px !important; }
    .mes .mes_timer { right: 10px !important; }
}


/* --- 名字：白底索引贴卡片，位于正文上方 --- */
.mes > .ch_name, .mes .mes_block > .ch_name { 
    /* 1. 重置之前的绝对定位，使其回到正常的排版流中 */
    display: flex !important; 
    position: relative !important; 
    top: auto !important;
    bottom: auto !important; 
    transform: none !important; /* 取消倾斜，看起来更像规整插入的索引卡 */

    /* 2. 样式：白色底，无边框 */
    background: #FFFFFF !important;
    border: none !important;
    border-radius: 8px 8px 0 0 !important; /* 顶部圆角，底部直角（与文件夹贴合） */

    /* 3. 关键：与文件夹正文的无缝拼接 */

    z-index: 20 !important; /* 确保层级高于背景，显示在最前面 */

    padding: 6px 16px 8px 16px !important; 
    align-items: center !important; 
    gap: 12px !important;

    /* 4. 手机端防截断核心代码 */
    width: fit-content !important; 
    max-width: 85% !important; /* 限制最大宽度，留出边缘呼吸感 */
    white-space: normal !important; /* 允许换行，覆盖原生可能存在的 nowrap */
    word-break: break-word !important; /* 遇到超长的英文名字自动换行 */
}

/* AI 名字：作为左侧索引贴 */
.mes[is_user="false"] > .ch_name, .mes[is_user="false"] .mes_block > .ch_name { 
    left: auto !important; 
    right: auto !important; 
    align-self: flex-start !important; /* 靠左对齐 */
    margin-left: 15px !important; /* 距离左边缘的缩进 */
}

/* 用户名字：作为右侧索引贴 */
.mes[is_user="true"] > .ch_name, .mes[is_user="true"] .mes_block > .ch_name { 
    left: auto !important; 
    right: auto !important; 
    align-self: flex-end !important; /* 靠右对齐 */
    margin-right: 15px !important; /* 距离右边缘的缩进 */
}

/* 名字字体微调 */
.mes .ch_name .name_text { 
    font-family: var(--font-english-script); 
    font-size: 20px !important; /* 从26px略微调小，放在索引贴里显得更精致 */
    letter-spacing: 1px; 
    color: var(--accent-blue) !important; 
    text-transform: uppercase; 
}
